package jsregexp

import (
	"unicode"

	"github.com/gruntjs/grunt-go/internal/jsrt/unicase"
)

// This file derives Unicode property membership from Go's unicode package, which
// carries the same Unicode version (17) as Node 24's ICU. Properties that Go does
// not provide, or provides only in part, are completed by the fix tables in
// props_tables.go, generated by comparing these predicates with Node 24's
// \p{...} over every code point.

// isAssigned reports whether r has a General_Category other than Cn. Go's
// unicode.C table includes unassigned code points, so the C subcategories are
// listed one by one.
func isAssigned(r rune) bool {
	return unicode.In(r, unicode.L, unicode.M, unicode.N, unicode.P, unicode.S, unicode.Z,
		unicode.Cc, unicode.Cf, unicode.Co, unicode.Cs)
}

// gcPredicate returns membership in the General_Category value with the given
// short name ("Lu", "L", "LC", "Cn", ...).
func gcPredicate(name string) func(rune) bool {
	switch name {
	case "Cn":
		return func(r rune) bool { return !isAssigned(r) }
	case "LC":
		return func(r rune) bool { return unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lt) }
	}
	t := unicode.Categories[name]
	return func(r rune) bool { return unicode.Is(t, r) }
}

// scriptPredicate returns membership in the Script value with the given long
// name; "Unknown" is every code point without a script.
func scriptPredicate(name string) func(rune) bool {
	if name == "Unknown" {
		var withScript [(unicode.MaxRune + 1) / 64]uint64
		mark := func(lo, hi, stride uint32) {
			for c := lo; c <= hi; c += stride {
				withScript[c/64] |= 1 << (c % 64)
			}
		}
		for _, t := range unicode.Scripts {
			for _, r := range t.R16 {
				mark(uint32(r.Lo), uint32(r.Hi), uint32(r.Stride))
			}
			for _, r := range t.R32 {
				mark(r.Lo, r.Hi, r.Stride)
			}
		}
		return func(r rune) bool { return withScript[r/64]&(1<<(r%64)) == 0 }
	}
	t := unicode.Scripts[name]
	return func(r rune) bool { return unicode.Is(t, r) }
}

// binaryPredicate returns membership in the binary property with the given long
// name, derived from the definitions in the Unicode Character Database. Emoji
// properties, Bidi_Mirrored and Changes_When_NFKC_Casefolded have no Go source
// and come entirely from the fix tables.
func binaryPredicate(name string) func(rune) bool {
	if t, ok := unicode.Properties[name]; ok {
		return func(r rune) bool { return unicode.Is(t, r) }
	}
	isPatternSyntax := func(r rune) bool {
		return unicode.In(r, unicode.Pattern_Syntax, unicode.Pattern_White_Space)
	}
	idStart := func(r rune) bool {
		return unicode.In(r, unicode.L, unicode.Nl, unicode.Other_ID_Start) && !isPatternSyntax(r)
	}
	idContinue := func(r rune) bool {
		return idStart(r) || unicode.In(r, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc, unicode.Other_ID_Continue) && !isPatternSyntax(r)
	}
	switch name {
	case "ASCII":
		return func(r rune) bool { return r < 0x80 }
	case "Any":
		return func(rune) bool { return true }
	case "Assigned":
		return isAssigned
	case "Alphabetic":
		return func(r rune) bool {
			return unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lt, unicode.Lm, unicode.Lo, unicode.Nl, unicode.Other_Alphabetic)
		}
	case "Lowercase":
		return func(r rune) bool { return unicode.In(r, unicode.Ll, unicode.Other_Lowercase) }
	case "Uppercase":
		return func(r rune) bool { return unicode.In(r, unicode.Lu, unicode.Other_Uppercase) }
	case "Cased":
		return func(r rune) bool {
			return unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lt, unicode.Other_Lowercase, unicode.Other_Uppercase)
		}
	case "Case_Ignorable":
		return unicase.IsCaseIgnorable
	case "Math":
		return func(r rune) bool { return unicode.In(r, unicode.Sm, unicode.Other_Math) }
	case "ID_Start", "XID_Start":
		return idStart
	case "ID_Continue", "XID_Continue":
		return idContinue
	case "Default_Ignorable_Code_Point":
		return func(r rune) bool {
			return unicode.In(r, unicode.Other_Default_Ignorable_Code_Point, unicode.Cf, unicode.Variation_Selector) &&
				!unicode.In(r, unicode.White_Space, unicode.Prepended_Concatenation_Mark)
		}
	case "Grapheme_Extend":
		return func(r rune) bool { return unicode.In(r, unicode.Mn, unicode.Me, unicode.Other_Grapheme_Extend) }
	case "Grapheme_Base":
		return func(r rune) bool {
			return isAssigned(r) && !unicode.In(r, unicode.Cc, unicode.Cf, unicode.Cs, unicode.Co, unicode.Zl, unicode.Zp,
				unicode.Mn, unicode.Me, unicode.Other_Grapheme_Extend)
		}
	case "Changes_When_Lowercased":
		return func(r rune) bool { return unicode.ToLower(r) != r }
	case "Changes_When_Uppercased":
		return func(r rune) bool { return unicode.ToUpper(r) != r }
	case "Changes_When_Titlecased":
		return func(r rune) bool { return unicode.ToTitle(r) != r }
	case "Changes_When_Casefolded":
		return func(r rune) bool { return unicode.ToLower(r) != r }
	case "Changes_When_Casemapped":
		return func(r rune) bool {
			return unicode.ToLower(r) != r || unicode.ToUpper(r) != r || unicode.ToTitle(r) != r
		}
	}
	return func(rune) bool { return false }
}
